// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 extra, uint256 amount) public {
        vm.assume(extra <= VALUE_CAP);
        extra = bound(extra, 0, 1e30);
        amount = bound(amount, 0, extra);
        vm.assume(amount < extra); // balance strictly exceeds requested amount

        // fund the contract beyond `amount` through its payable fallback
        vm.deal(address(this), extra);
        (bool okPay,) = address(c).call{value: extra}("");
        assertTrue(okPay);

        uint256 before = address(c).balance;
        assertTrue(before == extra);

        // owner (this test contract) withdraws exactly `amount`
        c.withdraw(amount);

        // General rule: balance decreases by exactly the requested amount.
        assertTrue(address(c).balance == before - amount);
    }
}
